const fonts=[['霞鹜文楷','LXGW WenKai','song','开源 / SIL OFL'],['思源黑体','Source Han Sans','hei','开源 / OFL'],['朱雀仿宋','Zhuque Fangsong','song','免费商用'],['寒蝉全圆体','Cubic 11','display','免费商用'],['得意黑','Smiley Sans','display','开源 / OFL'],['仓耳今楷','CangEr JinKai','hand','免费商用'],['阿里妈妈数黑体','Alibaba Sans','hei','免费商用'],['站酷小薇LOGO体','ZCOOL XiaoWei','display','免费商用'],['落霞孤鹜','LuoXia GuWu','hand','免费商用']];const grid=document.querySelector('#fontGrid'),search=document.querySelector('#search'),preview=document.querySelector('#previewText');let filter='all',limit=6;const labels={song:'宋体',hei:'黑体',hand:'手写',display:'艺术'};
function render(){const q=search.value.trim().toLowerCase(),items=fonts.filter(f=>(filter==='all'||f[2]===filter)&&(!q||f[0].toLowerCase().includes(q)||f[1].toLowerCase().includes(q))).slice(0,limit);grid.innerHTML=items.map((f,i)=>`<article class="font-card"><div class="card-top"><span class="tag">${labels[f[2]]}</span><button class="favorite" aria-label="收藏 ${f[0]}">♡</button></div><div class="specimen" style="font-family:${i%3===0?'var(--serif)':'inherit'}">${preview.value||'春风得意马蹄疾'}</div><div class="font-name">${f[0]}</div><div class="font-meta">${f[1]}　·　${f[3]}</div></article>`).join('');document.querySelector('#empty').style.display=items.length?'none':'block';document.querySelector('#loadMore').style.display=items.length>=Math.min(limit,fonts.length)?'block':'none';document.querySelectorAll('.favorite').forEach(b=>b.onclick=()=>{b.classList.toggle('saved');b.textContent=b.classList.contains('saved')?'♥':'♡'});}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelector('.tab.active').classList.remove('active');b.classList.add('active');filter=b.dataset.filter;limit=6;render()});search.oninput=render;preview.oninput=render;document.querySelector('#clearPreview').onclick=()=>{preview.value='春风得意马蹄疾  ·  Hello, world!';render()};document.querySelector('#loadMore').onclick=()=>{limit=fonts.length;render();document.querySelector('#loadMore').style.display='none'};document.querySelectorAll('.view').forEach(b=>b.onclick=()=>{document.querySelector('.view.active').classList.remove('active');b.classList.add('active');grid.style.gridTemplateColumns=b.dataset.view==='list'?'1fr':''});document.querySelector('#themeToggle').onclick=()=>document.body.classList.toggle('dark');document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();search.focus()}});render();
